"""Build the accessible, network-independent archive HTML from the reviewed manifest."""
import json
from html import escape
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
def e(value):
    return escape(str(value), quote=True)
def build():
    works = json.loads((ROOT / 'content/art-collection.json').read_text(encoding='utf-8'))
    first = works[0]
    options = {}
    for key in ('topic', 'type', 'period', 'museum'):
        options[key] = ''.join(f'<option value="{e(value)}">{e(value)}</option>' for value in sorted({w[key] for w in works}))
    from collections import Counter
    counts = Counter(w['museum'] for w in works)
    sources = ''.join(f'<li>{e(museum)} · {count} works</li>' for museum, count in sorted(counts.items()))
    cards = []
    for w in works:
        cards.append(f'''<article class="art-card" data-card="{w['id']}">
<a class="picture" href="{e(w['image'])}" data-open="{w['id']}" aria-label="Explore {e(w['title'])} by {e(w['artist'])}"><img src="{e(w['thumbnail'])}" alt="{e(w['title'])}" width="{w['width']}" height="{w['height']}" loading="lazy" decoding="async"></a>
<div class="art-info"><div class="art-type">{e(w['type'])}</div><h3>{e(w['title'])}</h3><p class="meta">{e(w['artist'])}<br>{e(w['date'])}</p><a href="{e(w['source'])}" target="_blank" rel="noopener" class="meta">{e(w['museum'])} ↗</a><a href="{e(w['image'])}" data-open="{w['id']}" class="button secondary">Explore this work</a></div></article>''')
    page = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#23382e">
<title>Christian Art — Daily Bread</title><meta name="description" content="Discover a new Christian artwork each day. Explore {len(works)} historical paintings, illuminated manuscripts, Bible illustrations, drawings and stained glass, with museum provenance and open-access images.">
<link rel="stylesheet" href="assets/christian-art.css"><script defer src="assets/christian-art.js"></script></head><body>
<header class="top"><div class="shell"><a class="brand" href="index.html">✝ <i>Daily Bread</i></a><nav class="nav" aria-label="Main navigation"><a href="index.html#today">Today's Verse</a><a href="index.html#world">Today's World</a><a href="index.html#church">The Church</a><a href="index.html#journal">Journal</a><a href="index.html#library">Scripture</a><a href="art.html" aria-current="page">Christian Art</a><button id="art-theme" aria-label="Toggle dark mode" aria-pressed="false">☾ Dark</button></nav></div></header>
<main><section class="intro shell"><div class="eyebrow">A daily encounter with beauty</div><h1>Christian Art</h1><p class="lede">Centuries of faith, seen through the hands of artists. Discover a work each day, linger over its details, and explore the stories that have inspired generations.</p><div class="intro-links"><a href="#archive">Explore the collection ↓</a><a href="#about-collection">About the images & their sources</a></div></section>
<div class="shell"><section class="feature" aria-label="Daily featured artwork"><figure class="feature-image"><img id="daily-image" src="{first['image']}" alt="{e(first['title'])} — {e(first['artist'])}" width="{first['width']}" height="{first['height']}" fetchpriority="high"><figcaption id="daily-caption">Collection: {e(first['museum'])} · Image reuse: {e(first['rights'])}</figcaption></figure><div class="feature-copy" id="daily-copy" aria-live="polite"><div class="eyebrow">From the collection</div><h2>{e(first['title'])}</h2><p>{e(first['artist'])} · {e(first['date'])}</p><p>{e(first['context'])}</p><a href="{first['source']}">Museum record & provenance ↗</a></div></section>
<div class="date-nav" id="date-controls" hidden><button class="button secondary" id="previous-day" aria-label="Previous day's artwork">← Previous day</button><label for="art-date">Choose a day</label><input type="date" id="art-date"><button class="button secondary" id="next-day" aria-label="Next day's artwork">Next day →</button><button class="button secondary" id="back-today">Today</button></div>
<p class="noscript-note" id="art-status" role="status" hidden></p><noscript><p class="noscript-note">Browse the complete collection below. Open an image to study it, or visit its museum record. Daily rotation and filters need JavaScript.</p></noscript>
<section class="archive" id="archive" aria-labelledby="archive-title"><div class="archive-heading"><div><div class="eyebrow">The collection</div><h2 id="archive-title">Art that invites us to look closer.</h2></div><p>{len(works)} works · seven forms of sacred art<br>Paintings, drawings, manuscripts, prints, stained glass, textiles and sculpture.</p></div>
<div id="art-controls" hidden><div class="filters"><label for="art-search">Search the collection<input type="search" id="art-search" placeholder="Artist, title, Bible story…"></label><label for="topic">Subject<select id="topic" aria-label="Subject"><option value="">All subjects</option>{options['topic']}</select></label><label for="medium">Art form<select id="medium" aria-label="Art form"><option value="">All art forms</option>{options['type']}</select></label><label for="period">Period<select id="period" aria-label="Period"><option value="">All periods</option>{options['period']}</select></label><label for="museum">Collection source<select id="museum" aria-label="Collection source"><option value="">All collections</option>{options['museum']}</select></label></div><div class="result-bar"><p class="meta" id="art-count" role="status">{len(works)} works in the collection</p><button class="button secondary" id="clear-art">Clear filters</button></div></div>
<p class="empty" id="no-art" hidden>No works match these filters. Try a different subject, art form or search.</p><div class="gallery" id="art-gallery">{''.join(cards)}</div><div class="more-wrap"><button class="button secondary" id="more-art" hidden>Show 12 more works</button></div></section></div>
<section class="collection-note" id="about-collection"><div class="shell"><div class="eyebrow">A living inheritance</div><h2>Many centuries. Many ways of seeing.</h2><p>This collection brings together works from five museum collections, including the National Gallery of Art in Washington, the Walters Art Museum and the J. Paul Getty Museum, alongside The Metropolitan Museum of Art and Cleveland Museum of Art. It includes Ethiopian, Armenian and Byzantine Christian imagery as well as European works. It includes medieval manuscript leaves, Bible woodcuts, icons, stained glass and works on paper, alongside paintings from later centuries. Some images depict biblical events; others reflect devotional traditions or artistic interpretations.</p><ul>{sources}</ul><p><strong>Collection source and image rights are different.</strong> The museum name identifies where the work is held or the image was obtained. Public-domain or CC0 reuse is identified separately in each work’s credit. Each image is included under its museum’s public-domain or CC0 open-access terms. Copies are held with Daily Bread so that the gallery does not rely on external image servers. Artwork is shown in full; the enlarged view lets you explore the details. Museum records preserve titles, dates, attribution qualifications and provenance.</p><p>Reflections are written for Daily Bread and labelled separately from historical information. Scripture links are included where a direct connection has been identified. Art from different Christian traditions is presented for thoughtful appreciation.</p><p>A new featured work is selected by your local calendar date, cycling through all {len(works)} works before repeating while the collection remains unchanged. Use the date controls to explore other days. <a href="https://www.metmuseum.org/about-the-met/policies-and-documents/open-access" target="_blank" rel="noopener">Met Open Access ↗</a> · <a href="https://www.clevelandart.org/open-access" target="_blank" rel="noopener">Cleveland Open Access ↗</a></p></div></section></main>
<footer class="footer"><div class="shell"><a class="brand" href="index.html">✝ <i>Daily Bread</i></a><p>Scripture, reflection and the beauty of Christian art. Collection images are public domain or released under CC0; the exact reuse terms are stated with each work. Individual museum credits and saved source records are available in each work’s enlarged view.</p><a href="index.html">Return to Daily Bread</a><br><a class="contact-link" href="contact.html">Contact us or a member of clergy</a></div></footer>
<dialog id="work-dialog" aria-labelledby="work-title"><div class="dialog-head"><h2 id="work-title">Explore the artwork</h2><button class="button secondary" id="close-work" autofocus>Close ✕</button></div><div class="dialog-body"><div class="study-toolbar"><label for="zoom">Study the details</label><input type="range" id="zoom" min="1" max="3" step="0.5" value="1"><output id="zoom-label" for="zoom">Fit whole image</output></div><div class="study-canvas" id="study-canvas" tabindex="0" role="region" aria-label="Artwork detail; scroll to explore when enlarged"><img id="work-image" alt=""></div><div class="work-text" id="work-text"></div></div></dialog>
</body></html>
'''
    (ROOT / 'art.html').write_text(page, encoding='utf-8', newline='\n')
    return page
if __name__ == '__main__':
    build()
    print('Built Christian Art page.')
